using System.Windows;using System.Windows.Controls;using OdinVault.Manager.Wpf.ViewModels;namespace OdinVault.Manager.Wpf.Views;public partial class DiscoverDatabasesWindow:Window{public bool AnyAdded{get;private set;}public DiscoverDatabasesWindow(){InitializeComponent();}void Password_Changed(object s,RoutedEventArgs e){if(DataContext is DiscoverDatabasesViewModel vm)vm.Password=((PasswordBox)s).Password;}async void Discover_Click(object s,RoutedEventArgs e){if(DataContext is DiscoverDatabasesViewModel vm)await vm.DiscoverAsync();}async void Add_Click(object s,RoutedEventArgs e){if(DataContext is DiscoverDatabasesViewModel vm){await vm.AddSelectedAsync();AnyAdded=true;}}}